const input = $input.first().json;
const boards = Array.isArray(input.board_tokens) && input.board_tokens.length > 0
  ? input.board_tokens
  : ['palantir', 'netflix', 'spotify'];

return boards.map(token => ({
  json: {
    board_token: token,
    api_url: `https://api.lever.co/v0/postings/${encodeURIComponent(token)}?mode=json&limit=50`,
    user_preferences: input.user_preferences || {}
  }
}));

const crypto = require('crypto');
const normalized = [];

for (const item of $input.all()) {
  const postings = Array.isArray(item.json) ? item.json : (Array.isArray(item.json?.data) ? item.json.data : []);
  for (const post of postings) {
    if (!post.id || !post.text) continue;
    const title = String(post.text).trim();
    const company = String(post.categories?.team || post.hostedUrl?.split('/')[3] || 'Lever Partner').trim();
    const location = String(post.categories?.location || 'Unspecified').trim();
    const commitment = String(post.categories?.commitment || 'full-time').toLowerCase();
    const workplaceType = String(post.workplaceType || 'unspecified').toLowerCase();

    const workMode = ['remote', 'hybrid', 'onsite'].includes(workplaceType)
      ? workplaceType
      : (location.toLowerCase().includes('remote') ? 'remote' : 'unspecified');

    const listText = Array.isArray(post.lists)
      ? post.lists.map(l => `${l.text}: ${String(l.content || '').replace(/<[^>]+>/g, ' ')}`).join('\n')
      : '';
    const fullDesc = `${post.descriptionPlain || ''}\n${listText}\n${post.additionalPlain || ''}`.trim();

    const appUrl = String(post.hostedUrl || post.applyUrl || '').trim();
    const canonicalUrl = appUrl.split('?')[0].replace(/\/+$/, '');
    const fallbackHash = crypto
      .createHash('sha256')
      .update(`${company.toLowerCase()}|${title.toLowerCase()}|${location.toLowerCase()}`)
      .digest('hex');
    const descHash = crypto.createHash('sha256').update(fullDesc).digest('hex');

    const salaryRange = post.salaryRange
      ? `${post.salaryRange.min || ''} - ${post.salaryRange.max || ''} ${post.salaryRange.currency || 'USD'}`
      : null;

    normalized.push({
      json: {
        job_id: `lever_${post.id}`,
        source: 'lever',
        title,
        company,
        location,
        work_mode: workMode,
        employment_type: commitment,
        experience_required: null,
        required_skills: [],
        preferred_skills: [],
        job_description: fullDesc,
        description_sha256: descHash,
        salary_range: salaryRange,
        posted_at: post.createdAt ? new Date(post.createdAt).toISOString() : new Date().toISOString(),
        application_url: appUrl,
        canonical_url: canonicalUrl,
        fallback_dedup_hash: fallbackHash,
        status: 'discovered'
      }
    });
  }
}

return normalized;
